// Shapes of /api/routines (src/ask_soony/routines.py) and small helpers shared by the routine UI.

export type Field = 'evidence' | 'headline' | 'option_action' | 'option_to' | 'supplier_name' | 'kind'
export type Channel = 'phone' | 'teams' | 'both'

export interface Cond { id: string; field: Field; op: 'contains' | 'is' | 'any_of'; value: string; text: string }
export interface Step {
  id: string
  do: 'carry_out' | 'notify' | 'log'
  text: string
  match?: { to?: string; action_contains?: string }
  channel?: Channel
  message?: string
}
export interface Spec { when: Cond[]; then: Step[] }

export interface Did {
  do: 'carry_out' | 'notify'
  card?: string; option?: string; text?: string; channel?: Channel; status?: string; dry?: boolean
}
export interface Run { at: string; ok: boolean; dry?: boolean; result?: unknown; error?: string; log?: string[]; did?: Did[] }
export interface Routine {
  id: string; name: string; description: string; spec?: Spec | null; code: string; enabled: boolean
  created_from?: string | null; created_at?: string; runs?: Run[]; handled?: number; note?: string
}

/** The fields the save, edit and preview endpoints take. */
export const body = (r: Routine) => ({
  id: r.id, name: r.name, description: r.description, spec: r.spec, created_from: r.created_from ?? null,
})

/** POST that keeps the server's reason on failure (FastAPI puts it in `detail`). */
export async function call<T>(url: string, payload: unknown = {}, method = 'POST'): Promise<T> {
  const r = await fetch(url, {
    method, headers: { 'Content-Type': 'application/json' }, body: method === 'DELETE' ? undefined : JSON.stringify(payload),
  })
  if (!r.ok) {
    let reason = ''
    try { reason = String((await r.json()).detail ?? '') } catch { /* not JSON */ }
    throw new Error(reason || `the server answered ${r.status}`)
  }
  return r.json()
}

export const newId = (prefix: string) => `${prefix}${Math.random().toString(36).slice(2, 8)}`

/** Steps a buyer can add with one click or drag. */
export const PALETTE: { key: string; label: string; make: () => Step }[] = [
  { key: 'phone', label: 'Tell me on my phone', make: () => ({ id: newId('s'), do: 'notify', channel: 'phone', message: '{headline}', text: 'Tell me on my phone' }) },
  { key: 'teams', label: 'Tell me on Teams', make: () => ({ id: newId('s'), do: 'notify', channel: 'teams', message: '{headline}', text: 'Tell me on Teams' }) },
  { key: 'log', label: 'Note it in the history', make: () => ({ id: newId('s'), do: 'log', message: 'Handled by a routine: {headline}', text: 'Note it in the history' }) },
]

export function paletteKey(s: Step): string | null {
  if (s.do === 'log') return 'log'
  if (s.do === 'notify' && (s.channel === 'phone' || s.channel === 'teams')) return s.channel
  return null
}

const where = (c?: Channel) => (c === 'phone' ? ' on your phone' : c === 'teams' ? ' on Teams' : '')

/** One line per thing a run did (or would do, in a test run). */
export function didLines(run: Run, spec?: Spec | null): { kind: 'send' | 'tell' | 'note'; channel?: Channel; text: string }[] {
  const out: { kind: 'send' | 'tell' | 'note'; channel?: Channel; text: string }[] = []
  for (const d of run.did ?? []) {
    if (d.do === 'carry_out') {
      out.push({ kind: 'send', text: `${d.dry ? 'Would send' : 'Sent'}: ${d.option ?? 'the message'}` })
    } else {
      out.push({ kind: 'tell', channel: d.channel, text: `${d.dry ? 'Would tell you' : 'Told you'}${where(d.channel)}: ${d.text ?? ''}` })
    }
  }
  // Lines from "note it" steps; the carry-out bookkeeping lines are already covered above.
  const sendTexts = (spec?.then ?? []).filter((s) => s.do === 'carry_out').map((s) => s.text)
  for (const line of run.log ?? []) {
    if (!line || sendTexts.some((t) => line.startsWith(t))) continue
    out.push({ kind: 'note', text: `${run.dry ? 'Would note' : 'Noted'}: ${line}` })
  }
  return out
}

/** "Told you about 1 card", "Sent 2 messages", "Nothing to do" for the stats line. */
export function summarise(run: Run): string {
  if (!run.ok) return 'The last run failed'
  const did = run.did ?? []
  const sent = did.filter((d) => d.do === 'carry_out').length
  const told = new Set(did.filter((d) => d.do === 'notify').map((d) => d.card)).size
  const parts: string[] = []
  if (sent) parts.push(`Sent ${sent} message${sent === 1 ? '' : 's'}`)
  if (told) parts.push(`${sent ? 'told' : 'Told'} you about ${told} card${told === 1 ? '' : 's'}`)
  return parts.join(', ') || 'Nothing to do'
}
import { Loader2, Phone, Sparkles, Workflow } from 'lucide-react'
import { useCallback, useEffect, useRef, useState } from 'react'
import { Button } from '@/components/ui/button'
import { Sheet, SheetContent, SheetDescription, SheetTitle } from '@/components/ui/sheet'
import { fmtDay, fmtTime, type State } from '@/lib/api'
import { RoutineCard } from './routines/RoutineCard'
import { body, call, type Routine, type Run } from './routines/types'

// Routines the agents wrote after a person decided something by hand: a recipe of conditions
// and steps, compiled to small Python and run in the Monty sandbox on every check
// (routines.py). Here they are reviewed, changed, switched on or off, and drafted from a decision.

interface VoiceDraft { card_id: string; instruction?: string; at?: string; via?: string; routine: Routine; preview?: Run }

const HIDDEN_KEY = 'ask-soony.hidden-routine-drafts'
function readHidden(): Set<string> {
  try { return new Set(JSON.parse(localStorage.getItem(HIDDEN_KEY) ?? '[]') as string[]) } catch { return new Set() }
}

const DECIDED: Record<string, string> = {
  approved: 'Approved', sent: 'Sent', escalated: 'Passed on', dismissed: 'Dismissed',
}

export function Routines({
  state, onChanged, request,
}: { state: State; onChanged: () => void; request?: { cardId: string; k: number } | null }) {
  const [open, setOpen] = useState(false)
  const [items, setItems] = useState<Routine[]>([])
  const [draft, setDraft] = useState<{ routine: Routine; preview: Run } | null>(null)
  const [writing, setWriting] = useState<string | null>(null)
  const [error, setError] = useState('')
  // Drafts the voice assistant wrote during a call; "Not now" hides one on this device.
  const [voice, setVoice] = useState<VoiceDraft[]>([])
  const [hidden, setHidden] = useState<Set<string>>(readHidden)
  const [voiceEdits, setVoiceEdits] = useState<Record<string, { routine: Routine; preview: Run }>>({})
  const tested = useRef(new Set<string>())

  const load = useCallback(async () => {
    try {
      const [r, d] = await Promise.all([fetch('/api/routines'), fetch('/api/routines/drafts')])
      if (r.ok) setItems((await r.json()).routines)
      if (d.ok) setVoice(((await d.json()).drafts ?? []).filter((x: VoiceDraft) => x?.routine?.id))
    } catch { /* offline for a moment: keep the last list */ }
  }, [])
  useEffect(() => { void load() }, [load])
  useEffect(() => {
    void load()
    const t = window.setInterval(load, open ? 10000 : 30000)
    return () => clearInterval(t)
  }, [open, load])

  const waiting = voice.filter(
    (d) => !hidden.has(d.routine.id) && !items.some((r) => r.id === d.routine.id) && draft?.routine.id !== d.routine.id,
  )
  // Test each waiting voice draft once on today's inbox (its stored test may be hours old).
  useEffect(() => {
    if (!open) return
    for (const d of waiting) {
      const id = d.routine.id
      if (tested.current.has(id) || voiceEdits[id] || !d.routine.spec) continue
      tested.current.add(id)
      call<{ routine: Routine; preview: Run }>('/api/routines/preview', body(d.routine))
        .then((out) => setVoiceEdits((v) => (v[id] ? v : { ...v, [id]: { routine: { ...d.routine, code: out.routine.code }, preview: out.preview } })))
        .catch(() => { /* keep the stored test run */ })
    }
  }, [open, waiting, voiceEdits])
  function hideDraft(id: string) {
    const next = new Set(hidden).add(id)
    setHidden(next)
    try { localStorage.setItem(HIDDEN_KEY, JSON.stringify([...next])) } catch { /* private mode */ }
  }

  // Asked from the "automate this" offer: open and start drafting right away.
  useEffect(() => {
    if (!request) return
    setOpen(true)
    void suggest(request.cardId)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [request?.k])

  // Decisions made by hand; a card with a routine says so, the card behind an open draft is hidden.
  const automatedBy = new Map(items.filter((r) => r.created_from).map((r) => [r.created_from!, r.name]))
  const drafting = new Set([draft?.routine.created_from, ...waiting.map((d) => d.card_id)])
  const decided = state.cards.filter((c) => c.status in DECIDED && !drafting.has(c.id))
  const active = items.filter((r) => r.enabled).length
  const writingCard = state.cards.find((c) => c.id === writing)

  async function suggest(cardId: string) {
    setWriting(cardId); setError(''); setDraft(null)
    try {
      setDraft(await call<{ routine: Routine; preview: Run }>('/api/routines/suggest', { card_id: cardId }))
    } catch (e) {
      setError(`The agent could not write a routine: ${(e as Error).message}.`)
    } finally { setWriting(null) }
  }
  async function turnOn() {
    if (!draft) return
    await call('/api/routines', body(draft.routine))
    setDraft(null)
    await load()
  }
  const changed = () => { void load(); onChanged() }

  return (
    <>
      <button
        onClick={() => setOpen(true)}
        title={waiting.length ? `Routines: ${waiting.length} draft${waiting.length === 1 ? '' : 's'} from your call waiting` : 'Routines: what the agents do on their own'}
        aria-label={waiting.length ? `Routines, ${waiting.length} waiting for you` : active ? `Routines, ${active} on` : 'Routines'}
        className="relative inline-flex h-9 cursor-pointer items-center gap-2 whitespace-nowrap rounded-full border border-line bg-white px-2.5 text-sm font-semibold text-ink-2 hover:bg-panel lg:px-3"
      >
        <Workflow size={16} className={active ? 'text-ok' : ''} />
        <span className="hidden lg:inline">Routines</span>
        {waiting.length > 0 ? (
          <span className="absolute -right-1 -top-1 grid h-4 min-w-4 place-items-center rounded-full bg-ok px-1 text-[10px] font-bold text-white ring-2 ring-white">{waiting.length}</span>
        ) : active > 0 && (
          <span className="absolute -right-1 -top-1 grid h-4 min-w-4 place-items-center rounded-full bg-white px-1 text-[10px] font-bold text-ok ring-1 ring-ok/40">{active}</span>
        )}
      </button>
      <Sheet open={open} onOpenChange={setOpen}>
        <SheetContent className="sm:max-w-[560px]">
          <div className="border-b border-line px-6 pb-4 pt-6 pr-14">
            <SheetTitle className="text-xl font-bold leading-snug">Routines</SheetTitle>
            <SheetDescription className="mt-1 text-sm text-ink-2">
              Written by an agent from your decisions. They run in a closed sandbox on every check. Anything that costs money or changes the plan still comes to you.
            </SheetDescription>
          </div>
          <div className="flex-1 space-y-4 overflow-y-auto px-6 py-5">
            {waiting.length > 0 && (
              <h3 className="flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wide text-ok">
                <Phone size={13} /> Drafted from your call
              </h3>
            )}
            {waiting.map((d) => {
              const id = d.routine.id
              const cur = voiceEdits[id] ?? { routine: d.routine, preview: d.preview ?? { at: d.at ?? '', ok: true, dry: true } }
              return (
                <div key={`voice-${id}`} className="space-y-2">
                  {d.instruction && <p className="text-sm text-ink-2">You said: “{d.instruction}”</p>}
                  <RoutineCard
                    routine={cur.routine}
                    onChanged={changed}
                    draft={{
                      preview: cur.preview,
                      onTurnOn: async () => { await call('/api/routines', body(cur.routine)); hideDraft(id); await load() },
                      onDiscard: () => hideDraft(id),
                      onReplace: (routine, preview) => setVoiceEdits((v) => ({ ...v, [id]: { routine, preview } })),
                    }}
                  />
                </div>
              )
            })}
            {writing && (
              <div className="rounded-xl border-2 border-dashed border-ok/40 bg-ok/5 p-4 text-[15px]">
                <div className="flex items-center gap-2 font-semibold text-ok">
                  <Loader2 size={16} className="animate-spin" /> The agent is writing a routine from your decision…
                </div>
                {writingCard && (
                  <p className="mt-1 text-ink-2">
                    “{writingCard.headline}”. It builds the steps, checks them in the sandbox and tests them on today's inbox before you see them. This takes up to half a minute.
                  </p>
                )}
              </div>
            )}
            {draft && (
              <RoutineCard
                key={`draft-${draft.routine.id}`}
                routine={draft.routine}
                onChanged={changed}
                draft={{
                  preview: draft.preview,
                  onTurnOn: turnOn,
                  onDiscard: () => setDraft(null),
                  onReplace: (routine, preview) => setDraft({ routine, preview }),
                }}
              />
            )}
            {error && <p className="rounded-lg bg-stop/10 p-3 text-sm text-stop">{error}</p>}

            {items.length > 0 && <h3 className="pt-1 text-xs font-semibold uppercase tracking-wide text-ink-3">Your routines</h3>}
            {items.length === 0 && !draft && !writing && (
              <p className="text-[15px] text-ink-2">No routines yet. Decide a card, then let the agent handle the next one like it.</p>
            )}
            {items.map((r) => <RoutineCard key={r.id} routine={r} onChanged={changed} />)}

            <h3 className="pt-3 text-xs font-semibold uppercase tracking-wide text-ink-3">Automate a decision you made</h3>
            {decided.length === 0 && (
              <p className="text-sm text-ink-3">{draft ? 'Review the suggestion above.' : 'Nothing decided yet.'}</p>
            )}
            <div className="space-y-2">
              {decided.map((c) => (
                <div key={c.id} className="flex items-center justify-between gap-3 rounded-lg border border-line px-3 py-2.5">
                  <div className="min-w-0">
                    <div className="line-clamp-2 text-[15px] font-medium leading-snug">{c.headline}</div>
                    <div className="mt-0.5 text-xs text-ink-3">
                      {DECIDED[c.status]}{c.ui?.at ? ` · ${fmtDay(c.ui.at)} ${fmtTime(c.ui.at)}` : ''}
                    </div>
                  </div>
                  {automatedBy.has(c.id) ? (
                    <span className="max-w-[45%] shrink-0 text-right text-sm font-semibold text-ok">Automated · {automatedBy.get(c.id)}</span>
                  ) : (
                    <Button size="sm" variant="outline" className="shrink-0" disabled={!!writing} onClick={() => suggest(c.id)}>
                      <Sparkles size={14} /> {writing === c.id ? 'Writing…' : 'Automate cards like this'}
                    </Button>
                  )}
                </div>
              ))}
            </div>
          </div>
        </SheetContent>
      </Sheet>
    </>
  )
}
import { Filter, Lock, Radar } from 'lucide-react'
import type { ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { StepIcon } from './RoutineFlow'
import type { Run, Spec, Step } from './types'

// The routine as an automatic flow graph (n8n style), drawn from the recipe alone: trigger →
// one node per condition → one node per step, with the fixed guard as a side path off the step
// that sends. Counters come from the latest run (a test run shows a "Test run" tag).

const REFUSED = 'Needs you, it costs money or changes the plan'

interface Counts { matched: number; byStep: Map<string, string>; guard: number }

function count(spec: Spec, run?: Run): Counts | null {
  if (!run || !run.ok) return null
  const did = run.did ?? []
  const byStep = new Map<string, string>()
  const sent = did.filter((d) => d.do === 'carry_out').length
  const refused = did.filter((d) => d.do === 'notify' && (d.text ?? '').startsWith(REFUSED)).length
  const told = did.filter((d) => d.do === 'notify' && !(d.text ?? '').startsWith(REFUSED))
  const sendTexts = spec.then.filter((s) => s.do === 'carry_out').map((s) => s.text)
  const noted = (run.log ?? []).filter((l) => l && !sendTexts.some((t) => l.startsWith(t))).length
  for (const s of spec.then) {
    if (s.do === 'carry_out' && sent) byStep.set(s.id, `${sent} sent`)
    if (s.do === 'notify') {
      const n = told.filter((d) => d.channel === (s.channel ?? 'both')).length
      if (n) byStep.set(s.id, `${n} told`)
    }
    if (s.do === 'log' && noted) byStep.set(s.id, `${noted} noted`)
  }
  const handled = typeof run.result === 'number' ? run.result : new Set(did.map((d) => d.card)).size
  return { matched: handled, byStep, guard: refused }
}

function stepTitle(s: Step): string {
  if (s.do === 'carry_out') return 'Send it'
  if (s.do === 'log') return 'Note it'
  return s.channel === 'phone' ? 'Tell you on your phone' : s.channel === 'teams' ? 'Tell you on Teams' : 'Tell you'
}

function Node({
  icon, tone, title, text, badge, active, dashed, wide,
}: { icon: ReactNode; tone: string; title: string; text: string; badge?: string; active?: boolean; dashed?: boolean; wide?: boolean }) {
  return (
    <div
      className={cn(
        'relative w-full min-w-0 rounded-xl border p-2.5 shadow-[0_1px_2px_rgba(15,23,42,0.04)]',
        wide && 'lg:w-[210px] lg:shrink-0',
        dashed ? 'border-dashed border-ink-3/40 bg-panel' : 'border-line bg-white',
        active && 'ring-2 ring-emerald-500/35',
      )}
      title={text}
    >
      <div className="flex items-start gap-2.5">
        <div className={cn('grid h-8 w-8 shrink-0 place-items-center rounded-lg', tone)}>{icon}</div>
        <div className="min-w-0 flex-1">
          <div className="flex items-center justify-between gap-1.5">
            <div className="truncate text-[13px] font-semibold text-ink">{title}</div>
            {badge && (
              <span
                className={cn(
                  'shrink-0 whitespace-nowrap rounded-full px-1.5 py-px text-[11px] font-semibold ring-1',
                  active ? 'bg-emerald-50 text-emerald-700 ring-emerald-600/20' : 'bg-panel text-ink-3 ring-line',
                )}
              >
                {badge}
              </span>
            )}
          </div>
          <div className={cn('mt-0.5 line-clamp-2 text-[12.5px] leading-snug text-ink-2', wide && 'lg:line-clamp-3')}>{text}</div>
        </div>
      </div>
    </div>
  )
}

const stroke = (dashed?: boolean) => ({ stroke: 'currentColor', strokeWidth: 1.25, fill: 'none', strokeDasharray: dashed ? '3 3' : undefined })
const Down = ({ dashed }: { dashed?: boolean }) => (
  <svg width="10" height="22" viewBox="0 0 10 22" aria-hidden className="block"><line x1="5" y1="0" x2="5" y2="20" {...stroke(dashed)} /><path d="M1.5 16 L5 21 L8.5 16" {...stroke()} /></svg>
)
const Right = ({ dashed }: { dashed?: boolean }) => (
  <svg width="28" height="10" viewBox="0 0 28 10" aria-hidden className="block"><line x1="0" y1="5" x2="26" y2="5" {...stroke(dashed)} /><path d="M22 1.5 L27 5 L22 8.5" {...stroke()} /></svg>
)

/**
 * A thin line with a small arrow. The main path runs down (narrow) or right (wide view on a large
 * screen); a side branch runs the other way.
 */
function Arrow({ wide, dashed, side }: { wide?: boolean; dashed?: boolean; side?: boolean }) {
  // On a phone the side branch drops below the step instead of beside it.
  const narrow = side ? (
    <>
      <div className="ml-[26px] sm:hidden"><Down dashed={dashed} /></div>
      <div className="mt-[21px] hidden sm:block"><Right dashed={dashed} /></div>
    </>
  ) : <div className="ml-[26px]"><Down dashed={dashed} /></div>
  if (!wide) return <div className="shrink-0 text-ink-3/70">{narrow}</div>
  const large = side ? <div className="ml-[26px]"><Down dashed={dashed} /></div> : <div className="mt-[21px]"><Right dashed={dashed} /></div>
  return (
    <div className="shrink-0 text-ink-3/70">
      <div className="lg:hidden">{narrow}</div>
      <div className="hidden lg:block">{large}</div>
    </div>
  )
}

export function FlowGraph({ spec, run, wide }: { spec: Spec; run?: Run; wide?: boolean }) {
  const c = count(spec, run)
  const sendAt = spec.then.findIndex((s) => s.do === 'carry_out')
  const guard = (
    <Node
      wide={wide}
      dashed
      icon={<Lock size={15} className="text-ink-2" />}
      tone="bg-white ring-1 ring-line"
      title="You decide"
      text="Costs money or changes the plan? It comes to you."
      badge={c?.guard ? `${c.guard} to you` : undefined}
      active={!!c?.guard}
    />
  )
  // Columns of the main path. Conditions stack in one column (they all have to hold); the step
  // that sends carries the guard as a side branch.
  const columns: { key: string; node: ReactNode }[] = [
    {
      key: 'trigger',
      node: (
        <Node
          wide={wide}
          icon={<Radar size={15} className="text-ok" />}
          tone="bg-ok/10"
          title="Every portal check"
          text="New files, replies and open decisions, about every minute"
          badge={run?.dry ? 'Test run' : undefined}
        />
      ),
    },
    {
      key: 'when',
      node: (
        <div className="flex flex-col">
          {spec.when.map((cond, i) => (
            <div key={cond.id}>
              {i > 0 && <Arrow />}
              <Node
                wide={wide}
                icon={<Filter size={15} className="text-amber-700" />}
                tone="bg-amber-50"
                title={i === 0 ? 'If' : 'And'}
                text={cond.text}
                badge={i === spec.when.length - 1 && c ? `${c.matched} matched` : undefined}
                active={i === spec.when.length - 1 && !!c?.matched}
              />
            </div>
          ))}
        </div>
      ),
    },
    ...spec.then.map((s, i) => {
      const badge = c?.byStep.get(s.id)
      const node = (
        <Node
          wide={wide}
          icon={<StepIcon step={s} size={15} />}
          tone={s.do === 'log' ? 'bg-panel ring-1 ring-line' : 'bg-ok/10'}
          title={stepTitle(s)}
          text={s.text}
          badge={badge}
          active={!!badge}
        />
      )
      if (i !== sendAt) return { key: s.id, node }
      return {
        key: s.id,
        node: (
          <div className={cn('flex flex-col sm:flex-row sm:items-start', wide && 'lg:flex-col')}>
            <div className={cn('min-w-0 sm:flex-[3]', wide && 'lg:flex-none')}>{node}</div>
            <Arrow wide={wide} side dashed />
            <div className={cn('min-w-0 pl-6 sm:flex-[2] sm:pl-0', wide && 'lg:flex-none')}>{guard}</div>
          </div>
        ),
      }
    }),
  ]
  if (sendAt < 0) columns.push({ key: 'guard', node: guard })

  return (
    <div className="relative">
      <div className={cn('flex flex-col', wide && 'lg:flex-row lg:items-start lg:overflow-x-auto lg:pb-2')}>
        {columns.map((col, i) => (
          <div key={col.key} className={cn('flex min-w-0 flex-col', wide && 'lg:flex-row lg:items-start')}>
            {i > 0 && <Arrow wide={wide} dashed={col.key === 'guard'} />}
            {col.node}
          </div>
        ))}
      </div>
    </div>
  )
}

