        </Sheet>
      )}
    </section>
  )
}

function Working({ text }: { text: string }) {
  return (
    <p className="mt-2 flex items-center gap-2 text-sm font-medium text-ok">
      <Loader2 size={14} className="animate-spin" /> {text}
    </p>
  )
}
import { BellRing, GripVertical, Lock, MessageSquare, NotebookPen, Plus, Send, Smartphone, X } from 'lucide-react'
import { useState, type DragEvent, type ReactNode } from 'react'
import { cn } from '@/lib/utils'
import { PALETTE, paletteKey, type Channel, type Cond, type Spec, type Step } from './types'

// One routine as blocks a buyer reads at a glance: WHEN (conditions), THEN (steps in order) and
// the fixed ALWAYS guard. With `before` it shows what a change does, block by block. With
// `onChange` the buyer edits directly: × removes, drag reorders, the palette adds steps.

type Mark = 'same' | 'added' | 'removed' | 'changed'
interface Row<T> { item: T; mark: Mark; old?: T; moved?: boolean }

/** Before and after merged by block id, removed blocks kept at their old place. */
function merge<T extends { id: string; text: string }>(after: T[], before?: T[]): Row<T>[] {
  if (!before) return after.map((item) => ({ item, mark: 'same' }))
  const old = new Map(before.map((b) => [b.id, b]))
  const now = new Set(after.map((a) => a.id))
  const commonBefore = before.filter((b) => now.has(b.id)).map((b) => b.id)
  const commonAfter = after.filter((a) => old.has(a.id)).map((a) => a.id)
  // Removed blocks hang after the last surviving block that preceded them.
  const anchored = new Map<string | null, T[]>()
  let anchor: string | null = null
  for (const b of before) {
    if (now.has(b.id)) { anchor = b.id; continue }
    anchored.set(anchor, [...(anchored.get(anchor) ?? []), b])
  }
  const gone = (key: string | null) => (anchored.get(key) ?? []).map((item): Row<T> => ({ item, mark: 'removed' }))
  const rows: Row<T>[] = gone(null)
  for (const a of after) {
    const b = old.get(a.id)
    const mark: Mark = !b ? 'added' : JSON.stringify(b) === JSON.stringify(a) ? 'same' : 'changed'
    const moved = !!b && commonBefore.indexOf(a.id) !== commonAfter.indexOf(a.id)
    rows.push({ item: a, mark, old: b, moved })
    rows.push(...gone(a.id))
  }
  return rows
}

function Tag({ mark, moved }: { mark: Mark; moved?: boolean }) {
  if (mark === 'added') return <span className="shrink-0 rounded bg-ok px-1.5 py-0.5 text-[11px] font-bold uppercase tracking-wide text-white">New</span>
  if (mark === 'removed') return <span className="shrink-0 text-[11px] font-bold uppercase tracking-wide text-stop">Removed</span>
  if (mark === 'changed') return <span className="shrink-0 text-[11px] font-bold uppercase tracking-wide text-ok">Changed</span>
  if (moved) return <span className="shrink-0 text-[11px] font-bold uppercase tracking-wide text-ok">Moved</span>
  return null
}

function Phrase({ row }: { row: Row<{ text: string }> }) {
  if (row.mark === 'changed' && row.old && row.old.text !== row.item.text) {
    return (
      <span>
        <span className="text-ink-3 line-through">{row.old.text}</span>{' '}
        <span>{row.item.text}</span>
      </span>
    )
  }
  return <span className={cn(row.mark === 'removed' && 'line-through')}>{row.item.text}</span>
}

const markClass = (m: Mark) =>
  m === 'added' ? 'bg-ok/5 ring-1 ring-ok/40' : m === 'removed' ? 'opacity-60' : m === 'changed' ? 'ring-1 ring-ok/40' : ''

export function StepIcon({ step, size = 16 }: { step: Pick<Step, 'do' | 'channel'>; size?: number }) {
  if (step.do === 'carry_out') return <Send size={size} className="text-ok" />
  if (step.do === 'log') return <NotebookPen size={size} className="text-ink-3" />
  return <ChannelIcon channel={step.channel} size={size} />
}

export function ChannelIcon({ channel, size = 16 }: { channel?: Channel; size?: number }) {
  if (channel === 'phone') return <Smartphone size={size} className="text-ok" />
  if (channel === 'teams') return <MessageSquare size={size} className="text-ok" />
  return <BellRing size={size} className="text-ok" />
}

const Connector = () => <div aria-hidden className="ml-6 h-3 w-px bg-line" />

function Block({ label, tone, children, className }: { label: string; tone?: 'ok'; children: ReactNode; className?: string }) {
  return (
    <div className={cn('rounded-lg border border-line bg-white px-3 py-2.5', className)}>
      <div className={cn('mb-2 text-xs font-bold uppercase tracking-wide', tone === 'ok' ? 'text-ok' : 'text-ink-3')}>{label}</div>
      {children}
    </div>
  )
}

function RemoveButton({ label, onClick }: { label: string; onClick: () => void }) {
  return (
    <button
      type="button"
      onClick={onClick}
      aria-label={label}
      title={label}
      className="grid h-5 w-5 shrink-0 cursor-pointer place-items-center rounded text-ink-3 opacity-0 transition-opacity hover:bg-stop/10 hover:text-stop focus-visible:opacity-100 group-hover:opacity-100"
    >
      <X size={13} />
    </button>
  )
}

type Drag = { kind: 'step'; id: string } | { kind: 'palette'; key: string }

export function RoutineFlow({
  spec, before, onChange, disabled,
}: { spec: Spec; before?: Spec; onChange?: (spec: Spec) => void; disabled?: boolean }) {
  const editable = !!onChange && !disabled
  const when = merge<Cond>(spec.when, before?.when)
  const then = merge<Step>(spec.then, before?.then)
  const [drag, setDrag] = useState<Drag | null>(null)
  const [dropAt, setDropAt] = useState<number | null>(null)
  const present = new Set(spec.then.map(paletteKey).filter(Boolean))
  const palette = PALETTE.filter((p) => !present.has(p.key))

  const change = (next: Partial<Spec>) => onChange?.({ ...spec, ...next })
  const removeCond = (id: string) => change({ when: spec.when.filter((c) => c.id !== id) })
  const removeStep = (id: string) => change({ then: spec.then.filter((s) => s.id !== id) })
  const addStep = (key: string, at = spec.then.length) => {
    const p = PALETTE.find((x) => x.key === key)
    if (!p) return
    const steps = [...spec.then]
    steps.splice(at, 0, p.make())
    change({ then: steps })
  }

  function readDrag(e: DragEvent): Drag | null {
    if (drag) return drag
    try { return JSON.parse(e.dataTransfer.getData('text/plain')) as Drag } catch { return null }
  }
  function start(e: DragEvent, d: Drag) {
    e.dataTransfer.setData('text/plain', JSON.stringify(d))
    e.dataTransfer.effectAllowed = d.kind === 'step' ? 'move' : 'copy'
    setDrag(d)
  }
  function end() { setDrag(null); setDropAt(null) }
  function over(e: DragEvent, index: number) {
    if (!editable) return
    e.preventDefault()
    e.stopPropagation() // the list's own handler would move the drop point to the end
    const box = (e.currentTarget as HTMLElement).getBoundingClientRect()
    setDropAt(e.clientY < box.top + box.height / 2 ? index : index + 1)
  }
  function drop(e: DragEvent) {
    e.preventDefault()
    const d = readDrag(e)
    const at = dropAt ?? spec.then.length
    end()
    if (!d || !editable) return
    if (d.kind === 'palette') return addStep(d.key, at)
    const from = spec.then.findIndex((s) => s.id === d.id)
    if (from < 0) return
    const steps = [...spec.then]
    const [moved] = steps.splice(from, 1)
    steps.splice(at > from ? at - 1 : at, 0, moved)
    if (steps.some((s, i) => s.id !== spec.then[i].id)) change({ then: steps })
  }

  // Position of each live step in `spec.then`, for drop targets (removed rows have none).
  const indexOf = new Map(spec.then.map((s, i) => [s.id, i]))
  const indicator = <div aria-hidden className="my-0.5 h-0.5 rounded-full bg-ok" />

  return (
    <div>
      <Block label="When">
        <div className="flex flex-wrap gap-1.5">
          {when.map((row) => (
            <span
              key={row.item.id}
              className={cn(
                'group inline-flex max-w-full items-start gap-1.5 rounded-md bg-panel px-2 py-1 text-sm leading-snug text-ink ring-1 ring-line',
                markClass(row.mark),
              )}
            >
              <Phrase row={row} />
              <Tag mark={row.mark} moved={false} />
              {editable && row.mark !== 'removed' && (
                <RemoveButton label="Remove this condition" onClick={() => removeCond(row.item.id)} />
              )}
            </span>
          ))}
        </div>
      </Block>
      <Connector />
      <Block label="Then" tone="ok">
        <ol
          className="space-y-1"
          onDragOver={(e) => { if (editable) { e.preventDefault(); if (dropAt == null) setDropAt(spec.then.length) } }}
          onDrop={drop}
          onDragLeave={(e) => { if (!e.currentTarget.contains(e.relatedTarget as Node)) setDropAt(null) }}
        >
          {then.map((row) => {
            const i = indexOf.get(row.item.id)
            const live = row.mark !== 'removed' && i != null
            return (
              <li key={row.item.id}>
                {live && dropAt === i && drag && indicator}
                <div
                  draggable={editable && live}
                  onDragStart={(e) => start(e, { kind: 'step', id: row.item.id })}
                  onDragEnd={end}
                  onDragOver={(e) => live && over(e, i)}
                  className={cn(
                    'group flex items-start gap-2 rounded-md px-1.5 py-1.5 text-[15px] leading-snug',
                    markClass(row.mark),
                    editable && live && 'cursor-grab hover:bg-panel active:cursor-grabbing',
                    drag?.kind === 'step' && drag.id === row.item.id && 'opacity-40',
                  )}
                >
                  {editable && (
                    <GripVertical size={14} className={cn('mt-0.5 shrink-0 text-ink-3 opacity-0', live && 'group-hover:opacity-100')} />
                  )}
                  <span className="mt-0.5 shrink-0"><StepIcon step={row.item} /></span>
                  <span className="min-w-0 flex-1"><Phrase row={row} /></span>
                  <Tag mark={row.mark} moved={row.moved} />
                  {editable && live && <RemoveButton label="Remove this step" onClick={() => removeStep(row.item.id)} />}
                </div>
              </li>
            )
          })}
          {dropAt === spec.then.length && drag && <li>{indicator}</li>}
        </ol>
        {editable && palette.length > 0 && (
          <div className="mt-2 flex flex-wrap items-center gap-1.5 border-t border-dashed border-line pt-2">
            <span className="mr-0.5 text-xs text-ink-3">Add a step</span>
            {palette.map((p) => (
              <button
                key={p.key}
                type="button"
                draggable
                onDragStart={(e) => start(e, { kind: 'palette', key: p.key })}
                onDragEnd={end}
                onClick={() => addStep(p.key)}
                title="Click to add, or drag it into place"
                className="inline-flex cursor-pointer items-center gap-1.5 rounded-full border border-dashed border-ok/50 bg-white px-2.5 py-1 text-[13px] font-medium text-ink-2 hover:border-ok hover:bg-ok/5 hover:text-ink"
              >
                <Plus size={12} className="text-ok" />
                <StepIcon step={p.make()} size={13} />
                {p.label}
              </button>
            ))}
          </div>
        )}
      </Block>
      <Connector />
      <div className="flex items-start gap-2.5 rounded-lg border border-dashed border-line bg-panel px-3 py-2.5">
        <Lock size={15} className="mt-0.5 shrink-0 text-ink-3" />
        <div>
          <div className="text-xs font-bold uppercase tracking-wide text-ink-3">Always</div>
          <div className="mt-0.5 text-[15px] text-ink-2">Costs money or changes the plan? It comes to you.</div>
        </div>
      </div>
    </div>
  )
}

content.content:
// What the main screen derives from /api/state: the inbox sections, near-identical cards grouped
// into one row, the one-sentence launch verdict and the countdown to the trucks. Nothing here
// knows about a specific supplier, part or number: it all comes from the cards and the strip.

import {
  DECIDED, LEVEL_RANK, fmtDay, fmtTime, tidy, viaOf, type ActivityItem, type Card, type State, type StripItem,
} from '@/lib/api'

/** Several cards with the same problem (same supplier, same headline once numbers are removed). */
export interface Group {
  key: string
  cards: Card[]
  /** The card shown for the group: the most urgent one. */
  lead: Card
}

const shape = (t: string) => tidy(t).replace(/\d[\d,.' ]*\d|\d/g, '#').replace(/\s+/g, ' ').trim().toLowerCase()
export const groupKey = (c: Card) => `${c.supplier_id ?? c.supplier_name ?? ''}|${c.kind ?? ''}|${shape(c.headline)}`

const deadlineMs = (c: Card) => (c.deadline ? new Date(c.deadline).getTime() : Number.POSITIVE_INFINITY)
/** Most urgent first: earliest decide-by time, then the worse level, then the bigger number. */
export const byUrgency = (a: Card, b: Card) =>
  deadlineMs(a) - deadlineMs(b) || LEVEL_RANK[b.level] - LEVEL_RANK[a.level] || (b.number ?? 0) - (a.number ?? 0)

export function groupCards(cards: Card[]): Group[] {
  const map = new Map<string, Card[]>()
  for (const c of [...cards].sort(byUrgency)) {
    const k = groupKey(c)
    map.set(k, [...(map.get(k) ?? []), c])
  }
  return [...map.entries()].map(([key, cs]) => ({ key, cards: cs, lead: cs[0] }))
}

/** "PO 4500318774, 4500318765 and 4500318786": what differs between the cards of a group. */
export function sameIssueOn(g: Group): string | null {
  if (g.cards.length < 2) return null
  const first = tidy(g.lead.headline)
  const firstTokens = new Set(first.match(/\d[\d,.]*\d|\d/g) ?? [])
  const lead = [...firstTokens].find((t) => t.replace(/\D/g, '').length >= 4) ?? [...firstTokens][0]
  // The word in front of the lead's own number ("PO") names what the others are.
  const word = lead ? first.slice(0, first.indexOf(lead)).trim().split(/\s+/).pop() : undefined
  const others = g.cards.slice(1).map((c) => {
    const toks = tidy(c.headline).match(/\d[\d,.]*\d|\d/g) ?? []
    return toks.find((t) => !firstTokens.has(t)) ?? tidy(c.headline)
  })
  const list = others.length > 1 ? `${others.slice(0, -1).join(', ')} and ${others[others.length - 1]}` : others[0]
  return word && /^[A-Za-z]{1,12}$/.test(word) ? `${word} ${list}` : list
}

export const routineOf = (state: State, cardId: string): string | null => {
  const a = state.activity.find((x) => x.card === cardId && viaOf(x)?.kind === 'routine')
  const v = a ? viaOf(a) : null
  return v?.kind === 'routine' ? v.name : null
}

export interface Handled {
  key: string
  card?: Card
  text: string
  at?: string
  routine: string | null
  status?: string
}

export interface Sections {
  needs: Group[]
  waiting: Card[]
  /** Decided by a routine (and routine actions without a card). */
  handled: Handled[]
  /** Decided by a person. */
  done: Card[]
}

export function sections(state: State): Sections {
  const open = state.cards.filter((c) => c.status === 'open')
  const needs = groupCards(open.filter((c) => !c.routed_to_other))
  const waiting = state.cards
    .filter((c) => (c.routed_to_other && c.status === 'open') || c.status === 'escalated')
    .sort(byUrgency)
  const decided = state.cards.filter((c) => DECIDED.includes(c.status) && c.status !== 'escalated')
  const handled: Handled[] = []
  const done: Card[] = []
  for (const c of decided) {
    const r = routineOf(state, c.id)
    if (r) {
      const a = state.activity.find((x) => x.card === c.id && viaOf(x)?.kind === 'routine')
      handled.push({ key: c.id, card: c, text: c.headline, at: a?.at ?? c.ui?.at, routine: r, status: c.status })
    } else done.push(c)
  }
  // Routine work that is not tied to a card on screen still counts as handled.
  state.activity.forEach((a: ActivityItem, i) => {
    const v = viaOf(a)
    if (v?.kind !== 'routine' || (a.card && state.cards.some((c) => c.id === a.card))) return
    handled.push({ key: `act-${i}`, text: a.text, at: a.at, routine: v.name })
  })
  const t = (x?: string) => (x ? new Date(x).getTime() : 0)
  handled.sort((a, b) => t(b.at) - t(a.at))
  done.sort((a, b) => t(b.ui?.at) - t(a.ui?.at))
  return { needs, waiting, handled, done }
}

// ---------------------------------------------------------------- clock

/** The launch moment (trucks leave): from the server's packing clock when it sends one. */
export function launchAt(state: State): string | null {
  const v = state.clock?.launch
  return v && !Number.isNaN(Date.parse(v)) ? v : null
}

/** "6 h 12 min", "1 d 4 h", "12 min". */
export function span(ms: number): string {
  const min = Math.max(0, Math.round(ms / 60000))
  if (min < 60) return `${min} min`
  const h = Math.floor(min / 60)
  if (h >= 24) return `${Math.floor(h / 24)} d ${h % 24} h`
  return `${h} h ${String(min % 60).padStart(2, '0')} min`
}

/** "10:00" today, "Mon 10:00" on another day. */
export function when(iso: string | null | undefined, nowMs: number): string {
  if (!iso) return ''
  return fmtDay(iso) === fmtDay(new Date(nowMs).toISOString()) ? fmtTime(iso) : `${fmtDay(iso)} ${fmtTime(iso)}`
}

// ---------------------------------------------------------------- the verdict

export type Bit = { text: string; tone?: 'stop' | 'warn' }

const plural = (n: number, one: string, many: string) => `${n} ${n === 1 ? one : many}`
const spare = (h: number) => (h < 1 ? `${Math.max(1, Math.round(h * 60))} min` : `${Math.round(h * 10) / 10} h`)

/**
 * One sentence for the whole launch, from the worst strip item: "Standard stops Sun 17:00 unless
 * you decide 3 things by 10:00." Only the words about the failing edition carry a colour.
 */
export function verdict(state: State, nowMs: number): Bit[] {
  const strip = state.strip
  if (!strip.length) return [{ text: 'Waiting for the first packing plan.' }]
  const bad = strip.filter((s) => s.level === 'red')
  const tight = strip.filter((s) => s.level === 'amber')
  const { needs } = sections(state)

  const tail = (items: StripItem[]): Bit[] => {
    const eds = new Set(items.map((s) => s.edition))
    const relevant = needs.filter((g) => g.cards.some((c) => !c.edition || eds.has(c.edition)))
    const ms = (x: string) => new Date(x).getTime()
    const dl = items.map((s) => s.breaks_first?.deadline).filter((x): x is string => !!x).sort((a, b) => ms(a) - ms(b))[0]
    const due = dl ? relevant.filter((g) => g.lead.deadline && ms(g.lead.deadline) <= ms(dl)) : relevant
    const n = (due.length ? due : relevant).length
    if (!n) return [{ text: '.' }]
    return [{ text: ` unless you decide ${plural(n, 'thing', 'things')}${dl && due.length ? ` by ${when(dl, nowMs)}` : ''}.` }]
  }
  const say = (s: StripItem, tone: 'stop' | 'warn'): Bit => {
    const stops = s.stops_at ?? s.breaks_first?.stops_at
    if (tone === 'warn') return { text: `${s.label} is tight`, tone }
    const at = stops ? when(stops, nowMs) : ''
    if (!stops) return { text: `${s.label} runs short`, tone }
    const past = new Date(stops).getTime() <= nowMs
    return { text: `${s.label} ${past ? 'stopped' : 'stops'} ${/^\d/.test(at) ? 'at ' : ''}${at}`, tone }
  }
  const join = (bits: Bit[]): Bit[] => bits.flatMap((b, i) => (i ? [{ text: ' and ' }, b] : [b]))

  if (bad.length) return [...join(bad.map((s) => say(s, 'stop'))), ...tail(bad)]
  if (tight.length) {
    const s = tight[0]
    const h = s.slack_hours
    return [say(s, 'warn'), { text: h != null && h > 0 ? `: ${spare(h)} spare` : '' }, ...tail(tight)]
  }
  const all = strip.length === 2 ? 'Both editions make' : strip.length === 1 ? `${strip[0].label} makes` : 'All editions make'
  const least = strip.filter((s) => s.slack_hours != null).sort((a, b) => a.slack_hours! - b.slack_hours!)[0]
  return [
    { text: `${all} the trucks.` },
    ...(least && least.slack_hours! > 0 ? [{ text: ` ${least.label} has ${spare(least.slack_hours!)} spare.` }] : []),
  ]
}

// ---------------------------------------------------------------- evidence

const SYSTEM = /system|sap|erp|plan|book stock/i
const PAPER = /paper|document|scan|advice|confirmation|delivery note|notice|invoice|report|offer|email/i

/** The contradiction a card is about: what the system says against what a document says. */
export function mismatchPair(card: Card): { sys: number; doc: number } | null {
  const sys = card.evidence.findIndex((e) => SYSTEM.test(e.source ?? '') && e.value != null)
  const doc = card.evidence.findIndex(
    (e, i) => i !== sys && !SYSTEM.test(e.source ?? '') && PAPER.test(e.source ?? '') && e.value != null,
  )
  return sys >= 0 && doc >= 0 ? { sys, doc } : null
}

const LANG: Record<string, string> = { KR: 'Korean', KO: 'Korean', CN: 'Chinese', ZH: 'Chinese', PL: 'Polish', EN: 'English', DE: 'German' }
/** "Korean" for a source labelled "(KR/EN)": the original language, not the English copy. */
export function languageOf(source: string | undefined, language?: string): string | null {
  const codes = [...(language ? [language] : []), ...((source ?? '').match(/\(([A-Z]{2}(?:\/[A-Z]{2})*)\)/)?.[1].split('/') ?? [])]
  const named = codes.map((c) => LANG[c.toUpperCase()]).filter(Boolean)
  return named.find((l) => l !== 'English') ?? named[0] ?? null
}

/** The source's name without the "System says ·" prefix and the language tag. */
export const sourceName = (src: string | undefined) =>
  tidy((src ?? '').replace(/^(System|Paper) says\s*·?\s*/i, '').replace(/\s*\([A-Z]{2}(?:\/[A-Z]{2})*\)\s*$/, '')).trim()

/** "48,000 due Sat 21 Nov" -> big "48,000", small "due Sat 21 Nov". */
export function splitValue(v: string | number | undefined): { big: string; rest: string } {
  const s = tidy(String(v ?? ''))
  const m = s.match(/^([−-]?\d[\d,.' ]*\d|\d)\b\s*(.*)$/)
  if (m && m[1].length <= 9) return { big: m[1].trim(), rest: m[2] }
  return { big: s, rest: '' }
}
export type Level = 'red' | 'amber' | 'grey' | 'blue'

export interface Option {
  index: number
  action?: string
  cost?: string
  effect?: string
  recommended: boolean
  draft?: string
  to?: string
  channel?: string
  routine_type?: string | null
}
export interface Evidence {
  source?: string
  value?: string | number
  doc?: string
  page?: number
  quote?: string
  translation?: string
  language?: string
  unit?: string
}
export interface TrailStep { agent?: string; at?: string; text?: string }

export interface Card {
  id: string
  kind?: string
  part?: string
  /** Short readable name of the part code, from the master data ("Art Book"). */
  part_name?: string | null
  headline: string
  summary?: string
  number: number | null
  number_label: string
  edition?: string
  cell_hours_lost?: number
  slack_hours?: number
  deadline?: string
  runs_dry?: string | null
  /** When the late goods arrive, if a finding states it (may be after launch). */
  arrives_at?: string | null
  severity?: string
  level: Level
  status: string
  approver?: string
  routed_to_other: boolean
  reason?: string
  called_at?: string
  options: Option[]
  evidence: Evidence[]
  trail: TrailStep[]
  supplier_id?: string
  supplier_name?: string
  shipment?: string
  routes: string[]
  ui: {
    status?: string; at?: string; note?: string
    // Supplier reply tied back by the alert agent (replies.py)
    reply?: string; reply_from?: string; reply_at?: string; reply_text?: string
  }
  escalation_brief: string
}

export interface MapNode { id: string; kind: 'supplier' | 'port' | 'dc' | 'site'; name: string; lat: number; lon: number; country?: string }
export interface Leg { id: string; origin: string; destination: string; mode: string; via?: string; path: [number, number][] | null }
export interface Shipment {
  id: string; route_id: string; mode: string; supplier_id: string; status: string
  eta?: string; etd?: string; progress: number; departed: boolean; silent: boolean; silent_hours?: number
  level: Level; note?: string
}
export interface StripItem {
  edition: string; label: string; level: Level; status: string
  copies_at_risk: number; slack_hours: number | null
  breaks_first: { text?: string; deadline?: string; stops_at?: string | null; card: string } | null
  finishes_at?: string | null
  stops_at?: string | null
}

/** One edition on the packing clock: when its line finishes, or stops for want of parts. */
export interface ClockEdition {
  edition: string
  label: string
  level: Level
  /** Last copy packed at plan rate; null if the line stops first or the shifts run out. */
  finishes_at: string | null
  /** Line runs out of parts (projected; never at night); null if it does not stop. */
  stops_at: string | null
  /** Largest copies-at-risk figure on the edition's open cards, or the verifier's if higher. */
  copies_at_risk: number
  slack_hours: number | null
  remaining: number | null
  rate_per_hour: number | null
  /** When the packed count behind `remaining` was taken; packing is projected at plan rate since. */
  packed_as_of: string | null
  /** Copies the hours left cannot pack even with every part present. */
  short_of_time: number | null
  breaks_first_card: string | null
}
export interface Clock {
  /** Trucks leave: the end of the last shift. */
  launch: string
  /** Shift windows [start, end] from the start of today until launch, ISO. */
  windows: [string, string][]
  editions: ClockEdition[]
}
export interface EventItem { id: string; at: string; path?: string; file?: string; node?: string }
export interface ActivityItem {
  at?: string; text: string; kind: string; detail?: string | null; card?: string
  /** Who handled it: "inbox", "voice" or "routine: <name>". Missing on older items. */
  via?: string | null
}

export interface State {
  now: string
  viewer: string
  portal_found: boolean
  map: { nodes: MapNode[]; legs: Leg[]; version: string }
  route_level: Record<string, Level>
  badges: Record<string, number>
  shipments: Shipment[]
  strip: StripItem[]
  clock?: Clock
  cards: Card[]
  inbox_ids: string[]
  calm: boolean
  events: EventItem[]
  activity: ActivityItem[]
  last_drop_at: string | null
  last_check_at: string | null
  read_since_6: number
  trust: Record<string, string>
}

export async function fetchState(): Promise<State> {
  const r = await fetch('/api/state')
  if (!r.ok) throw new Error(`state ${r.status}`)
  return r.json()
}

export async function post<T = unknown>(url: string, body: unknown = {}): Promise<T> {
  const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) })
  if (!r.ok) throw new Error(`${url} ${r.status}`)
  return r.json()
}

export const COLORS: Record<Level, string> = {
  blue: '#1d6fe0',
  amber: '#d97706',
  red: '#dc2626',
  grey: '#7b8494',
}
export const LEVEL_RANK: Record<Level, number> = { red: 3, amber: 2, grey: 1, blue: 0 }

const TZ = 'Europe/Berlin'
export const fmtTime = (iso?: string | null) =>
  iso ? new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: TZ }).format(new Date(iso)) : ''
export const fmtDay = (iso?: string | null) =>
  iso ? new Intl.DateTimeFormat('en-GB', { weekday: 'short', timeZone: TZ }).format(new Date(iso)) : ''
export const fmtNum = (n: number | null | undefined) => (n == null ? '–' : Math.round(n).toLocaleString('en-GB'))

export function ago(iso: string | null | undefined, nowMs: number): string {
  if (!iso) return 'never'
  const min = Math.max(0, Math.round((nowMs - new Date(iso).getTime()) / 60000))
  if (min < 1) return 'just now'
  if (min < 60) return `${min} min ago`
  const h = Math.floor(min / 60)
  return h < 48 ? `${h} h ago` : `${Math.floor(h / 24)} days ago`
}

export function until(iso: string | undefined, nowMs: number): { text: string; urgent: boolean } | null {
  if (!iso) return null
  const min = Math.round((new Date(iso).getTime() - nowMs) / 60000)
  if (min <= 0) return { text: 'now', urgent: true }
  const text = min < 60 ? `${min} min` : `${Math.floor(min / 60)} h ${min % 60 ? `${min % 60} min` : ''}`.trim()
  return { text: `in ${text}`, urgent: min < 180 }
}

export const DONE_WORD: Record<string, string> = {
  approved: 'Approved', sent: 'Sent', escalated: 'Escalated', dismissed: 'Dismissed',
}
export const DECIDED = Object.keys(DONE_WORD)

/** What handled an activity item, read from its `via` field. */
export function viaOf(a: ActivityItem): { kind: 'routine'; name: string } | { kind: 'voice' } | null {
  const v = (a.via ?? '').trim()
  if (/^routine\s*:/i.test(v)) return { kind: 'routine', name: v.replace(/^routine\s*:\s*/i, '') }
  if (/^voice$/i.test(v)) return { kind: 'voice' }
  return null
}

// Internal part / product codes (CMP-GAM-001, FG-GH6-STD): never shown on their own.
const CODE = /^[A-Z]{2,5}(-[A-Z0-9]+)+$/

/** A readable name for a part code, found on the cards; undefined if none has one. */
export function partName(part: string | undefined, cards: Card[]): string | undefined {
  if (!part) return undefined
  if (!CODE.test(part)) return part
  const c = cards.find(
    (c) => c.part && !CODE.test(c.part) && (c.id.endsWith(part) || c.options.some((o) => o.action?.includes(`(${part})`))),
  )
  return c?.part
}

const fmtDate = (ymd: string) =>
  new Intl.DateTimeFormat('en-GB', { weekday: 'short', day: 'numeric', month: 'short', timeZone: 'UTC' }).format(
    new Date(`${ymd}T00:00:00Z`),
  )

/** Display text: drop bracketed internal codes, write ISO dates as "Mon 23 Nov". */
export function tidy(t: string | undefined | null): string {
  if (!t) return ''
  return t
    .replace(/\s*\((?:[A-Z]{2,5}-)+[A-Z0-9-]+\)/g, '')
    .replace(/\b(\d{4}-\d{2}-\d{2})(?:T[\d:.]+(?:Z|[+-]\d{2}:\d{2})?)?\b/g, (_, d: string) => fmtDate(d))
}

const cap = (t: string) => (t ? t[0].toUpperCase() + t.slice(1) : t)

/** One cost wording everywhere. */
export function costText(cost: string | undefined | null): string {
  const c = (cost ?? '').trim()
  if (!c || /^(none|no cost|free|0|-|–|n\/a)$/i.test(c)) return 'No cost'
  return cap(tidy(c))
}
export const sentence = (t: string | undefined | null) => cap(tidy(t))

/** Slack as people say it; "–" when it would only confuse (on track, or nothing at risk). */
export function slackText(hours: number | null, onTrack: boolean, atRisk: number): string {
  if (hours == null || (onTrack && (hours < 0 || atRisk === 0))) return '–'
  const sign = hours < 0 ? '−' : ''
  const a = Math.abs(hours)
  if (a < 1) return `${sign}${Math.round(a * 60)} min`
  return `${sign}${Math.round(a * 10) / 10} h`
}

