import { Menu } from 'lucide-react'
import { useEffect, useRef, useState, type ReactNode } from 'react'
import { ago } from '@/lib/api'
import type { State } from '@/lib/api'
import { launchAt, span, verdict } from '@/lib/decisions'
import { cn } from '@/lib/utils'

export type View = 'launch' | 'suppliers'

interface Props {
  state: State
  nowMs: number
  view: View
  onView: (v: View) => void
  /** The Routines button (opens its sheet), shown as a tab. */
  routines: ReactNode
  bell: ReactNode
  compact?: boolean
}

// One row: who is watching, one sentence on the launch, the time left and where to go.
export function Header({ state, nowMs, view, onView, routines, bell, compact }: Props) {
  const bits = verdict(state, nowMs)
  return (
    <header className="flex h-16 shrink-0 items-center gap-3 border-b border-line bg-white px-4 lg:gap-6 lg:px-6">
      <Brand state={state} nowMs={nowMs} compact={compact} />
      {!compact && (
        <p className="min-w-0 flex-1 text-balance text-center text-[16px] font-semibold leading-snug text-ink" aria-live="polite">
          {bits.map((b, i) => (
            <span key={i} className={b.tone === 'stop' ? 'text-stop' : b.tone === 'warn' ? 'text-warn' : undefined}>{b.text}</span>
          ))}
        </p>
      )}
      <div className={cn('flex shrink-0 items-center gap-3', compact && 'ml-auto')}>
        <Countdown state={state} nowMs={nowMs} />
        {compact ? (
          <PhoneMenu view={view} onView={onView} routines={routines} />
        ) : (
          <nav className="flex items-center gap-0.5 rounded-lg bg-panel p-0.5 ring-1 ring-line" aria-label="Views">
            <Tab on={view === 'launch'} onClick={() => onView('launch')}>Launch</Tab>
    </button>
  )
}

function PhoneMenu({ view, onView, routines }: { view: View; onView: (v: View) => void; routines: ReactNode }) {
  const [open, setOpen] = useState(false)
  const ref = useRef<HTMLDivElement>(null)
  useEffect(() => {
    if (!open) return
    const off = (e: MouseEvent) => { if (!ref.current?.contains(e.target as Node)) setOpen(false) }
    document.addEventListener('mousedown', off)
    return () => document.removeEventListener('mousedown', off)
  }, [open])
  const item = (v: View, label: string) => (
    <button
      onClick={() => { onView(v); setOpen(false) }}
      className={cn('block w-full cursor-pointer rounded-lg px-3 py-2.5 text-left text-[15px] font-semibold hover:bg-panel', view === v ? 'text-ink' : 'text-ink-2')}
    >
      {label}
    </button>
  )
  return (
    <div ref={ref} className="relative">
      <button
        onClick={() => setOpen(!open)}
        aria-label="Menu"
        aria-expanded={open}
        className="grid h-9 w-9 cursor-pointer place-items-center rounded-full border border-line bg-white text-ink-2 hover:bg-panel"
      >
        <Menu size={18} />
      </button>
      {/* Kept mounted so the Routines sheet survives the menu closing. */}
      <div className={cn('absolute right-0 top-11 z-30 w-52 rounded-xl border border-line bg-white p-1 shadow-lg', !open && 'hidden')}>
        {item('launch', 'Launch')}
        <div className="tab-routines-menu px-1 py-1" onClick={() => setOpen(false)}>{routines}</div>
        {item('suppliers', 'Suppliers')}
      </div>
    </div>
  )
}
.tab-routines > button {
  height: 2rem;
  border: 0;
  border-radius: 6px;
  background: transparent;
  padding: 0 12px;
}
.tab-routines > button:hover { background: transparent; color: var(--color-ink); }
.tab-routines-menu > button {
  width: 100%;
  height: 2.5rem;
  justify-content: flex-start;
  border: 0;
  border-radius: 8px;
  padding: 0 8px;
  font-size: 15px;
}
.tab-routines-menu > button > span.hidden { display: inline; }
    const k = groupKey(c)
    return {
      more: state.cards.filter((x) => x.id !== c.id && x.status === 'open' && groupKey(x) === k).length,
      onYes: () => automateFrom(c),
      onNext: () => { setJustDecided(null); select(nextOpen(c.id)) },
    }
  }
  const routines = <Routines state={state} onChanged={load} request={automate} />

  // ------------------------------------------------------------ one decision (/d/<id>)
  const single = path.match(/^\/d\/(.+)$/)
  if (single) {
    const id = decodeURIComponent(single[1])
    const card = state.cards.find((c) => c.id === id)
    return (
      <div className="min-h-full bg-white">
        <div className="sticky top-0 z-20 flex h-14 items-center justify-between gap-3 border-b border-line bg-white/95 px-4 backdrop-blur">
          <button onClick={() => go('/')} className="cursor-pointer text-sm font-semibold text-ok hover:underline">← All decisions</button>
          <div className="flex items-center gap-2">{routines}<AlertsButton /></div>
        </div>
        <main className="mx-auto max-w-[900px] px-4 py-6 sm:px-8">
          {card ? (
            <DecisionPane
              key={card.id}
              card={card}
              state={state}
              nowMs={nowMs}
              group={groupOf(card)}
              direct
              onChanged={load}
              onDrawer={openDrawer}
              ringing={ringing && card.status === 'open'}
              onRingingDone={stopRinging}
              offer={offerFor(card) && { ...offerFor(card)!, onNext: () => { setJustDecided(null); const n = nextOpen(card.id); go(n ? `/d/${encodeURIComponent(n)}` : '/') } }}
            />
          ) : (
            <p className="text-ink-2">This decision is no longer open.</p>
          )}
        </main>
        <EvidenceDrawer view={drawer} onClose={() => setDrawer(null)} />
      </div>
    )
  }

  const selected = selectedId ? state.cards.find((c) => c.id === selectedId) ?? null : null
  const openOnPhone = (id: string) => go(`/d/${encodeURIComponent(id)}`)
  const timeline = (
    <LaunchTimeline
      state={state}
      nowMs={nowMs}
      selectedId={selectedId}
      onSelect={(id) => (phone ? openOnPhone(id) : select(id))}
      compact={phone}
    />
  )
  const header = (
    <Header state={state} nowMs={nowMs} view={view} onView={setView} routines={routines} bell={<AlertsButton />} compact={phone} />
  )
  const toggle = (key: string) =>
    setExpanded((e) => { const n = new Set(e); if (n.has(key)) n.delete(key); else n.add(key); return n })
  const list = (
    <DecisionList
      state={state}
      nowMs={nowMs}
      sec={sec}
      selectedId={phone ? null : selectedId}
      onSelect={phone ? openOnPhone : select}
      expanded={expanded}
      onToggle={toggle}
      fresh={fresh}
    />
  )
  const suppliers = (
    <div className="flex min-h-0 flex-1 flex-col">
      <div className="relative min-h-[420px] flex-1">
        <SupplyMap state={state} hoverRoutes={[]} selection={mapSel} onSelect={setMapSel} pulseNode={pulseNode} />
      </div>
      <Legend />
    </div>
  )
  const overlays = (
    <>
      {toast && (
        <div className="toast-in fixed left-1/2 top-20 z-50 -translate-x-1/2 rounded-xl border border-line bg-white px-5 py-3 text-[15px] font-semibold shadow-lg">
          <span className="mr-2 inline-block h-2.5 w-2.5 animate-pulse rounded-full bg-ok" />
          {toast}
        </div>
      )}
      <EvidenceDrawer view={drawer} onClose={() => setDrawer(null)} />
    </>
  )

  // ------------------------------------------------------------ phone
  if (phone) {
    return (
      <div className="flex min-h-full flex-col bg-white">
        <div className="sticky top-0 z-20">{header}</div>
        {view === 'launch' ? (
          <>
            <VerdictLine state={state} nowMs={nowMs} />
            <div className="border-b border-line">{timeline}</div>
            <div className="px-1">{list}</div>
          </>
        ) : suppliers}
        {overlays}
      </div>
    )
  }

  // ------------------------------------------------------------ desktop
  const openCount = sec.needs.length
  return (
    <div className="flex h-full flex-col bg-white">
      {header}
      {view === 'launch' ? (
        <>
          <div className="shrink-0 border-b border-line">{timeline}</div>
          <div className="flex min-h-0 flex-1">
            <aside className="scroll-thin w-[372px] shrink-0 overflow-y-auto border-r border-line px-2" aria-label="Decisions">
              {list}
            </aside>
            <main className="scroll-thin min-w-0 flex-1 overflow-y-auto">
              <div className="mx-auto max-w-[900px] px-8 py-8 xl:px-12">
                {selected ? (
                  <DecisionPane
                    key={selected.id}
                    card={selected}
                    state={state}
                    nowMs={nowMs}
                    group={groupOf(selected)}
                    keys
                    onChanged={load}
                    onDrawer={openDrawer}
                    offer={offerFor(selected)}
                  />
                ) : (
                  <div className="grid min-h-[40vh] place-items-center text-center">
                    {openCount === 0 ? (
                      <p className="max-w-md text-[16px] leading-relaxed text-ink-2">
                        <span className="block text-[20px] font-bold text-ink">Nothing needs you.</span>
                        Agents are watching {state.shipments.length} shipments; last check {ago(state.last_check_at, nowMs)}.
                      </p>
                    ) : (
                      <p className="text-[16px] text-ink-2">Pick a decision, or press <kbd>J</kbd>.</p>
                    )}
