import json, os, copy, time
from playwright.sync_api import sync_playwright

D = '/Users/jonasstenglein/.claude/jobs/3021cc1a/tmp/ui-routines'
BASE = os.environ.get('BASE', 'http://127.0.0.1:8011')
fx = json.load(open(f'{D}/suggest.json'))
draft = fx['routine']
spec = copy.deepcopy(draft['spec'])
spec['then'].insert(1, {"id": "s9", "do": "notify", "channel": "phone", "message": "{headline}", "text": "Tell me on my phone"})
saved = {**copy.deepcopy(draft), "id": "demo1", "enabled": True, "spec": spec, "handled": 3,
         "name": "Collect goods ready at the port", "created_from": "other-card",
         "runs": [{"at": "2026-11-22T10:42:00+01:00", "ok": True, "dry": False, "result": 2,
                   "did": [{"do": "carry_out", "card": "a", "option": "Ask the DC site lead to collect 4,200 clear cases at CTA Hamburg", "status": "sent"},
                           {"do": "notify", "card": "a", "channel": "phone", "text": "Collect Game Card Case (clear) from the port"},
                           {"do": "notify", "card": "b", "channel": "both", "text": "Needs you, it costs money or changes the plan: Book a truck for steel cases"}],
                   "log": ["Send a message to the DC site lead to collect the shipment from the port.: x (sent)", "Automatically told the DC site lead to collect goods."]}]}
legacy = {"id": "old1", "name": "Tell DC site lead to collect at port", "description": "When a container is ready at the port, tell the DC site lead.", "code": "for card in open_cards():\n    pass\n", "enabled": False, "runs": []}
draft_preview = {"at": "2026-11-22T10:50:00+01:00", "ok": True, "dry": True, "result": 1,
                 "did": [{"do": "carry_out", "card": "a", "option": "Ask the DC site lead to collect 4,200 clear cases at CTA Hamburg", "dry": True}], "log": []}
edit_after = copy.deepcopy(draft)
edit_after['spec']['then'].append({"id": "s7", "do": "notify", "channel": "teams", "message": "{headline}", "text": "Tell me on Teams"})
edit_after['spec']['when'][3]['text'] = "The message goes to the DC site lead or the warehouse team."
edit_after['spec']['when'] = [c for c in edit_after['spec']['when'] if c['id'] != 'c2']

def fulfill(route, data, status=200, delay=0):
    if delay: time.sleep(delay)
    route.fulfill(status=status, content_type='application/json', body=json.dumps(data))

def handler(route):
    req = route.request; url = req.url.split('?')[0]; m = req.method
    if url.endswith('/api/routines') and m == 'GET':
        return fulfill(route, {"routines": [saved, legacy]})
    if url.endswith('/api/routines/drafts'):
        return fulfill(route, {"drafts": [{"card_id": "voice-card", "instruction": "next time just tell the warehouse yourself", "at": "2026-11-22T10:30:00+01:00", "via": "voice",
                                           "routine": {**copy.deepcopy(draft), "id": "voice1", "name": "Tell the warehouse when goods are at the port", "created_from": "voice-card"}, "preview": draft_preview}]})
    if url.endswith('/api/routines/suggest'):
        return fulfill(route, {"routine": {**draft, "created_from": "collect-CMP-GAM-003"}, "preview": draft_preview}, delay=1.2)
    if url.endswith('/api/routines/edit'):
        return fulfill(route, {"after": edit_after, "note": "", "preview": draft_preview}, delay=0.8)
    if url.endswith('/api/routines/preview'):
        return route.continue_()   # real, dry run only
    if '/api/routines' in url:     # save, toggle, run, delete: never hit the server
        return fulfill(route, {"ok": True, "at": "2026-11-22T10:55:00+01:00", "did": []})
    return route.continue_()

def shot(page, name):
    page.screenshot(path=f'{D}/shots/{name}.png'); print('shot', name)

with sync_playwright() as p:
    b = p.chromium.launch(channel='chrome')
    for w, h, tag in [(1440, 900, 'wide'), (390, 844, 'phone')]:
        ctx = b.new_context(viewport={'width': w, 'height': h}, device_scale_factor=2 if tag == 'wide' else 2)
        page = ctx.new_page()
        page.goto(BASE + '/login')
        if page.locator('input[name=password]').count():
            page.fill('input[name=password]', os.environ['PW'])
            page.press('input[name=password]', 'Enter')
        else:
            page.goto(BASE + '/')
        page.wait_for_load_state('networkidle')
        page.route('**/api/routines**', handler)
        page.reload(); page.wait_for_timeout(1500)
        if tag == 'wide':
            page.screenshot(path=f'{D}/shots/header.png', clip={'x': 700, 'y': 0, 'width': 740, 'height': 70})
        page.get_by_role('button', name='Routines').first.click(); page.wait_for_timeout(600)
        shot(page, f'{tag}-1-list-flow')
        if tag == 'phone':
            page.locator('[role=dialog] .overflow-y-auto').first.evaluate('e => e.scrollTop = 400'); page.wait_for_timeout(200)
            shot(page, 'phone-2-scrolled'); ctx.close(); continue
        page.get_by_role('tab', name='Steps').first.click(); page.wait_for_timeout(300)
